const raw = String(input.raw || vars.inputDataUid || vars.targetUrl || '').trim()
if (!raw) throw new Error('fb_resolve_url: missing input (raw + vars.inputDataUid + vars.targetUrl are empty)')

// Extract UID gốc — ưu tiên profile.php?id, fallback last segment của pathname
let uid = raw
try {
  const u = new URL(/^https?:\/\//i.test(raw) ? raw : 'https://' + raw)
  const idParam = u.searchParams.get('id')
  if (idParam) {
    uid = idParam
  } else {
    const parts = u.pathname.split('/').filter(Boolean)
    if (parts.length > 0) {
      // Loại bỏ prefix 'groups' nếu có (vd /groups/164... → uid = 164...)
      uid = parts[parts.length - 1]
