  if (!source || !suffix || source === suffix) return ''
  const idx = source.lastIndexOf(suffix)
  if (idx < 0) return ''
  return (source.slice(0, idx) + source.slice(idx + suffix.length))
    .replace(/\n{3,}/g, '\n\n')
