    total: batchRawCount,
    postIndex,
    nextCursor: cursor,
    batchId,
    batchIndex: nextBatchIndex,
    batchSize,
    batchRawCount,
    batchStartCursor
  };
`, selectors.post, state.cursor, state.newsfeedBatchId || '', state.newsfeedBatchIndex || 0, state.newsfeedBatchSize || 0, state.loadPostDelayMs, state.newsfeedBatchRawCount || 0).catch(() => ({
