return await helpers.zaloFindPhoneUser({
  phone: vars.targetPhone,
  inputData: vars.inputData,
  targetName: vars.inputDataName
});

return await helpers.zaloSendPhoneMessage({
  target: input.zaloTarget,
  enabled: vars.enableMessage,
  message: vars.campaignContent,
  attachments: vars.images,
  inputData: vars.inputData
});

return await helpers.zaloSendPhoneFriendRequest({
  target: input.zaloTarget,
  enabled: vars.enableAddFriend,
  message: vars.friendRequestMessage,
  inputData: vars.inputData
});

return await helpers.zaloApplyContactTag({
  target: input.zaloTarget,
  enabled: vars.enableZaloTag,
  labelId: vars.zaloTagId,
  labelName: vars.zaloTagName
});

return await helpers.zaloChangeContactAlias({
  target: input.zaloTarget,
  enabled: vars.enableZaloAlias,
  alias: vars.zaloAlias,
  inputData: vars.inputData
});

return await helpers.emailSendMessage({
  to: vars.targetEmail,
  subject: vars.emailSubject,
  body: vars.campaignContent,
  isHtml: vars.emailBodyIsHtml,
  enableClickTracking: vars.emailCheckLinkClicks,
  attachments: vars.images,
  inputData: vars.inputData,
  targetName: vars.inputDataName
});

return await helpers.zaloSendFriendMessage({
  targetUid: vars.targetUid || vars.inputDataUid,
  targetName: vars.targetName || vars.inputDataName,
  message: vars.campaignContent,
  attachments: vars.images,
  inputData: vars.inputData
});

return await helpers.zaloSendGroupMessage({
  targetUid: vars.targetUid || vars.inputDataUid,
  targetName: vars.targetName || vars.inputDataName,
  message: vars.campaignContent,
  attachments: vars.images,
  inputData: vars.inputData
});

return await helpers.zaloResolveGroupMemberTarget({
  targetUid: vars.targetUid || vars.inputDataUid,
  targetName: vars.targetName || vars.inputDataName,
  inputData: vars.inputData
});

return await helpers.zaloSendPhoneMessage({
  target: input.zaloTarget,
  enabled: vars.enableMessage,
  message: vars.campaignContent,
  attachments: vars.images,
  inputData: vars.inputData
});

return await helpers.zaloSendPhoneFriendRequest({
  target: input.zaloTarget,
  enabled: vars.enableAddFriend,
  message: vars.friendRequestMessage,
  inputData: vars.inputData
});

return await helpers.zaloResolveRemarketingCustomerTarget({
  targetUid: vars.targetUid || vars.inputDataUid,
  targetName: vars.targetName || vars.inputDataName,
  inputData: vars.inputData
});

return await helpers.zaloSendPhoneMessage({
  target: input.zaloTarget,
  enabled: vars.enableMessage,
  message: vars.campaignContent,
  attachments: vars.images,
  inputData: vars.inputData
});

return await helpers.zaloSendPhoneFriendRequest({
  target: input.zaloTarget,
  enabled: vars.enableAddFriend,
  message: vars.friendRequestMessage,
  inputData: vars.inputData
});

return await helpers.zaloResolveFriendRecommendationTarget({
  targetUid: vars.targetUid || vars.inputDataUid,
  targetName: vars.targetName || vars.inputDataName,
  inputData: vars.inputData
});

return await helpers.zaloSendPhoneMessage({
  target: input.zaloTarget,
  enabled: vars.enableMessage,
  message: vars.campaignContent,
  attachments: vars.images,
  inputData: vars.inputData
});

return await helpers.zaloSendPhoneFriendRequest({
  target: input.zaloTarget,
  enabled: vars.enableAddFriend,
  message: vars.friendRequestMessage,
  inputData: vars.inputData
});

const enabled = vars.enableGroupPostShareToJoinedGroups === true || input.enableGroupPostShareToJoinedGroups === true;
const rawTargets = Array.isArray(vars.groupPostShareTargets)
  ? vars.groupPostShareTargets
  : (Array.isArray(input.groupPostShareTargets) ? input.groupPostShareTargets : []);
const maxSelect = Math.min(3, Math.max(0, Math.floor(Number(vars.groupPostShareMaxCount ?? input.groupPostShareMaxCount ?? 3))));
const stepMs = Math.max(0, Number(vars.facebookStepMs || input.facebookStepMs || 1000));

const targets = rawTargets
  .map(item => {
    const record = item && typeof item === 'object' ? item : {};
    return {
      id: Number(record.id),
      name: String(record.name || '').replace(/\s+/g, ' ').trim(),
      uid: String(record.uid || '').trim()
    };
  })
  .filter(item => Number.isFinite(item.id) && item.id > 0 && item.name)
  .slice(0, 10);

if (!enabled || maxSelect <= 0 || targets.length === 0 || !page) {
  return {
    enabled,
    skipped: true,
    reason: !enabled ? 'disabled' : maxSelect <= 0 ? 'no_quota_capacity' : targets.length === 0 ? 'no_candidates' : 'no_page',
    candidateCount: targets.length,
    attemptedCount: 0,
    selectedCount: 0,
    selectedTargets: []
  };
}

const addButton = await helpers.element('AddGroupToPostBtn');
const searchInput = await helpers.element('SearchAddGroupToPostInp');
const selectTemplate = await helpers.element('SelectGroupToPostChk');
const confirmButton = await helpers.element('ConfirmGroupToPostBtn');
const backButton = await helpers.element('BackToPostFormBtn');

function xpathLiteral(value) {
  const text = String(value || '');
  if (!text.includes("'")) return "'" + text + "'";
  if (!text.includes('"')) return '"' + text + '"';
  return "concat('" + text.replace(/'/g, "',\"'\",'") + "')";
}

function selectorForGroupName(template, groupName) {
  const literal = xpathLiteral(groupName);
  if (template.includes("'$group_name'")) return template.replace(/'\$group_name'/g, literal);
  if (template.includes('"$group_name"')) return template.replace(/"\$group_name"/g, literal);
  return template.replace(/\$group_name/g, groupName);
}

async function rawClick(xpath) {
  return await page.evaluate(`
    const xpath = String(__args[0] || '');
    function firstByXPath(value) {
      try {
        return document.evaluate(value, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
      } catch (e) {
        return null;
      }
    }
    const el = firstByXPath(xpath);
    if (!el) return { found: false, clicked: false };
    try { el.scrollIntoView({ block: 'center', inline: 'center' }); } catch (e) {}
    const init = { bubbles: true, cancelable: true, view: window };
    try { el.dispatchEvent(new PointerEvent('pointerdown', Object.assign({}, init, { pointerId: 1, pointerType: 'mouse' }))); } catch (e) {}
    try { el.dispatchEvent(new MouseEvent('mousedown', init)); } catch (e) {}
    try { el.dispatchEvent(new PointerEvent('pointerup', Object.assign({}, init, { pointerId: 1, pointerType: 'mouse' }))); } catch (e) {}
    try { el.dispatchEvent(new MouseEvent('mouseup', init)); } catch (e) {}
    try { el.click(); } catch (e) { return { found: true, clicked: false, message: e && e.message ? e.message : String(e) }; }
    return { found: true, clicked: true };
  `, xpath).catch(err => ({ found: false, clicked: false, message: err && err.message ? err.message : String(err) }));
}

async function rawClear(xpath) {
  return await page.evaluate(`
    const xpath = String(__args[0] || '');
    function firstByXPath(value) {
      try {
        return document.evaluate(value, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
      } catch (e) {
        return null;
      }
    }
    const el = firstByXPath(xpath);
    if (!el) return { found: false, cleared: false };
    try { el.focus(); } catch (e) {}
    try {
      if (typeof el.select === 'function') el.select();
      else if (typeof el.setSelectionRange === 'function') el.setSelectionRange(0, String(el.value || '').length);
    } catch (e) {}
    try { document.execCommand('delete', false); } catch (e) {}
    if ('value' in el) {
      const proto = Object.getPrototypeOf(el);
      const desc = proto ? Object.getOwnPropertyDescriptor(proto, 'value') : null;
      if (desc && typeof desc.set === 'function') desc.set.call(el, '');
      else el.value = '';
    }
    try { el.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'deleteContentBackward', data: null })); } catch (e) { el.dispatchEvent(new Event('input', { bubbles: true })); }
    el.dispatchEvent(new Event('change', { bubbles: true }));
    return { found: true, cleared: true };
  `, xpath).catch(err => ({ found: false, cleared: false, message: err && err.message ? err.message : String(err) }));
}

async function rawType(xpath, text) {
  return await page.evaluate(`
    const xpath = String(__args[0] || '');
    const text = String(__args[1] || '');
    function firstByXPath(value) {
      try {
        return document.evaluate(value, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
      } catch (e) {
        return null;
      }
    }
    const el = firstByXPath(xpath);
    if (!el) return { found: false, typed: false };
    try { el.focus(); } catch (e) {}
    if ('value' in el) {
      const proto = Object.getPrototypeOf(el);
      const desc = proto ? Object.getOwnPropertyDescriptor(proto, 'value') : null;
      if (desc && typeof desc.set === 'function') desc.set.call(el, text);
      else el.value = text;
    } else {
      try { document.execCommand('insertText', false, text); } catch (e) {}
    }
    try { el.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText', data: text })); } catch (e) { el.dispatchEvent(new Event('input', { bubbles: true })); }
    el.dispatchEvent(new Event('change', { bubbles: true }));
    return { found: true, typed: true };
  `, xpath, text).catch(err => ({ found: false, typed: false, message: err && err.message ? err.message : String(err) }));
}

let attemptedCount = 0;
let opened = false;
let confirmed = false;
const checkboxSelectedTargets = [];
let selectedTargets = [];

try {
  const openedResult = await rawClick(addButton);
  opened = openedResult && openedResult.clicked === true;
  if (!opened) {
    return {
      enabled: true,
      skipped: true,
      reason: openedResult && openedResult.found === false ? 'add_group_button_not_found' : 'add_group_button_not_clicked',
      candidateCount: targets.length,
      attemptedCount: 0,
      selectedCount: 0,
      selectedTargets: []
    };
  }
  await helpers.sleep(stepMs + 1000, signal);

  for (const target of targets) {
    if (checkboxSelectedTargets.length >= maxSelect) break;
    attemptedCount += 1;
    try {
      if (signal && signal.aborted) throw new Error('Aborted');
      const cleared = await rawClear(searchInput);
      if (!cleared || cleared.found !== true) continue;
      await helpers.sleep(stepMs + 500, signal);

      const typed = await rawType(searchInput, target.name);
      if (!typed || typed.found !== true) continue;
      await helpers.sleep(stepMs + 500, signal);

      const selectXpath = selectorForGroupName(selectTemplate, target.name);
      const selected = await rawClick(selectXpath);
      if (!selected || selected.clicked !== true) continue;
      checkboxSelectedTargets.push(target);
      await helpers.sleep(stepMs + 500, signal);
    } catch (err) {
      if (signal && signal.aborted) throw err;
    }
  }
} catch (err) {
  if (signal && signal.aborted) throw err;
  helpers.log('Không chọn được group share kèm: ' + (err && err.message ? err.message : String(err)));
} finally {
  if (opened) {
    try {
      if (checkboxSelectedTargets.length > 0) {
        const confirmResult = await rawClick(confirmButton);
        confirmed = confirmResult && confirmResult.clicked === true;
        if (confirmed) {
          selectedTargets = checkboxSelectedTargets;
          await helpers.sleep(stepMs + 500, signal);
        }
      } else {
        const backResult = await rawClick(backButton);
        if (backResult && backResult.clicked === true) await helpers.sleep(stepMs + 500, signal);
      }
    } catch (err) {
      if (signal && signal.aborted) throw err;
    }
  }
}

vars.groupPostShareSelectedTargets = selectedTargets;

return {
  enabled: true,
  skipped: false,
  candidateCount: targets.length,
  attemptedCount,
  checkboxSelectedCount: checkboxSelectedTargets.length,
  selectedCount: selectedTargets.length,
  confirmed,
  selectedTargets
};

if (vars.formattedContentEnabled !== true) return input

const sourceContentPlain = String(
  vars.copiedSourcePlainText || vars.sourceContentPlain || input.copiedSourcePlainText || input.sourceContentPlain || ''
)
const manualContentNative = String(
  vars.formattedManualContent || vars.manualContentNative || vars.campaignContent || ''
)

const composed = await page.evaluate(String.raw`
  const source = String(__args[0] || '');
  const manual = String(__args[1] || '');
  const allowed = new Set([
    'p', 'div', 'br', 'h1', 'h2', 'h3',
    'strong', 'b', 'em', 'i', 'u', 's', 'strike', 'del',
    'ul', 'ol', 'li', 'blockquote', 'a'
  ]);
  const discardWithContent = new Set(['script', 'style', 'iframe', 'object', 'embed', 'svg', 'math']);
  const escapeHtml = (value) => String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
  const renderNode = (node) => {
    if (node.nodeType === Node.TEXT_NODE) return escapeHtml(node.nodeValue || '');
    if (node.nodeType !== Node.ELEMENT_NODE) return '';
    const tag = String(node.tagName || '').toLowerCase();
    if (discardWithContent.has(tag)) return '';
    let children = Array.from(node.childNodes || []).map(renderNode).join('');
    if (!allowed.has(tag)) return children;
    if (tag === 'br') return '<br>';
    let attrs = '';
    const styles = [];
    if (tag === 'a') {
      const href = String(node.getAttribute('href') || '').trim();
      if (/^https?:\/\//i.test(href)) attrs += ' href="' + escapeHtml(href) + '"';
    }
    const style = String(node.getAttribute('style') || '');
    const align = style.match(/(?:^|;)\s*text-align\s*:\s*(left|center|right)\s*(?:;|$)/i);
    if (align && (tag === 'p' || /^h[1-3]$/.test(tag))) {
      styles.push('text-align: ' + align[1].toLowerCase());
    }
    const indentRaw = String(node.getAttribute('data-indent') || '').trim();
    const parsedIndent = Number(indentRaw);
    const indent = /^\d+$/.test(indentRaw) && Number.isSafeInteger(parsedIndent) && parsedIndent > 0
      ? Math.min(8, parsedIndent)
      : 0;
    const hasVisibleContent = String(node.textContent || '').replace(/\u00a0/g, ' ').trim().length > 0;
    if (indent > 0 && hasVisibleContent && !node.closest('li') && (tag === 'p' || /^h[1-3]$/.test(tag))) {
      children = '&#160;'.repeat(indent * 6) + children;
    }
    if (styles.length > 0) attrs += ' style="' + styles.join('; ') + '"';
    return '<' + tag + attrs + '>' + children + '</' + tag + '>';
  };
  const parsed = new DOMParser().parseFromString(manual, 'text/html');
  const safeManual = Array.from(parsed.body.childNodes || []).map(renderNode).join('').trim();
  const safeSource = source
    ? source
      .replace(/\r\n?/g, '\n')
      .split('\n')
      .map((line) => line ? '<p>' + escapeHtml(line) + '</p>' : '<p><br></p>')
      .join('')
      .trim()
    : '';
  return [safeSource, safeManual].filter(Boolean).join('<p><br></p>');
`, sourceContentPlain, manualContentNative)

vars.formattedManualContent = manualContentNative
vars.copiedSourcePlainText = sourceContentPlain
vars.sourceContentPlain = sourceContentPlain
vars.campaignContent = String(composed || '')

return {
  ...input,
  content: vars.campaignContent,
  campaignContent: vars.campaignContent,
  copiedSourcePlainText: sourceContentPlain,
  sourceContentPlain,
  manualContentNative
}

const mode = String(input.pageIdentityStateOperation || '')
if (mode === 'ready' || mode === 'restored') {
  if (input.ok !== true) throw new Error(String(input.message || (mode === 'ready' ? 'Không chuyển được sang Page đã chọn' : 'Không chuyển về được danh tính ban đầu')))
  vars.pageIdentityReady = mode === 'ready'
  return { ok: true, identityName: input.identityName }
}
if (mode === 'capture_result') { vars.pageIdentityResult = { ...input }; delete vars.pageIdentityResult.pageIdentityStateOperation; return vars.pageIdentityResult }
if (mode === 'result') return vars.pageIdentityResult || {}
throw new Error('Cấu hình trạng thái phiên Page không hợp lệ')

